/** Shared response boundary. Transport/rules enforce identity, time and moderation. */
export const CONTRACT_VERSION='0.1.0-draft.2';
const fail=message=>{throw new TypeError(message)};
function fields(value,allowed){if(!value||typeof value!=='object'||Array.isArray(value)||Object.keys(value).some(k=>!allowed.includes(k)))fail('Unknown response field');}
function text(value,max,label,empty=false){if(typeof value!=='string'||new TextEncoder().encode(value).length>max||(!empty&&!value.trim())||/[\uD800-\uDFFF]/u.test(value)||/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/u.test(value))fail('Invalid '+label);return value;}
function freeze(value){for(const x of Object.values(value))if(x&&typeof x==='object')freeze(x);return Object.freeze(value);}
export function contentRef(input){fields(input,['contentId','kind','language']);text(input.contentId,240,'content identity');if(/[\/\\\s]/u.test(input.contentId)||['.','..'].includes(input.contentId))fail('Unsafe content identity');if(!['poem','article'].includes(input.kind))fail('Invalid content kind');try{if(typeof input.language!=='string'||Intl.getCanonicalLocales(input.language).length!==1)fail('Invalid language')}catch{fail('Invalid language')}return freeze({...input});}
export function contentKey(ref){return encodeURIComponent(contentRef(ref).contentId);}
export function submissionId(value){if(typeof value!=='string'||!/^[A-Za-z0-9]{20}$/.test(value))fail('Stable submission ID required');return value;}
// Desired-state transaction: identical retries perform no write and never increment again.
export function likeTransition({liked,count},desired){if(typeof liked!=='boolean'||!Number.isSafeInteger(count)||count<0||typeof desired!=='boolean')fail('Invalid like state');if(liked&&count===0)fail('Inconsistent like state');const delta=liked===desired?0:desired?1:-1,next=count+delta;if(!Number.isSafeInteger(next)||next<0)fail('Invalid like count');return freeze({liked:desired,count:next,delta,write:delta!==0});}
export function commentSubmission(input){fields(input,['submissionId','contentId','kind','language','displayName','message','consentVersion']);const ref=contentRef({contentId:input.contentId,kind:input.kind,language:input.language});submissionId(input.submissionId);text(input.displayName,80,'display name');text(input.message,2000,'comment');if(input.consentVersion!=='public-comments-v1')fail('Explicit public-comment consent required');return freeze({...ref,submissionId:input.submissionId,displayName:input.displayName,message:input.message,consentVersion:input.consentVersion});}
export function privateFeedback(input){fields(input,['submissionId','contentId','kind','language','name','email','message','reason','consentVersion']);const ref=contentRef({contentId:input.contentId,kind:input.kind,language:input.language});submissionId(input.submissionId);text(input.name,120,'name');text(input.message,5000,'feedback');if(!['note','correction','submission'].includes(input.reason))fail('Invalid feedback reason');if(input.consentVersion!=='private-feedback-v1')fail('Explicit private-feedback consent required');if(input.email!==undefined){text(input.email,254,'email',true);if(input.email&&!/^[^@\s]+@[^@\s]+\.[^@\s]+$/u.test(input.email))fail('Invalid email');}return freeze({...ref,submissionId:input.submissionId,name:input.name,...(input.email!==undefined?{email:input.email}:{}),message:input.message,reason:input.reason,consentVersion:input.consentVersion});}
// Public projection is a separate approved document, never a redacted pending object.
export function publicComment(input){fields(input,['id','contentId','kind','language','displayName','message','publishedAt']);submissionId(input.id);const ref=contentRef({contentId:input.contentId,kind:input.kind,language:input.language});text(input.displayName,80,'display name');text(input.message,2000,'comment');if(!Number.isSafeInteger(input.publishedAt)||input.publishedAt<0)fail('Invalid public timestamp');return freeze({id:input.id,...ref,displayName:input.displayName,message:input.message,publishedAt:input.publishedAt});}
export function receipt(input){fields(input,['submissionId','channel','acceptedAt']);submissionId(input.submissionId);if(!['comment','feedback'].includes(input.channel)||!Number.isSafeInteger(input.acceptedAt)||input.acceptedAt<0)fail('Invalid receipt');return freeze({...input});}
